REG = {
  'string': lambda f, row: '*'*len(row[f['key']]) if f.get('isMasked') else row[f['key']],
  'badge':  lambda f, row: next(f"[{v['label']}]" for v in f['values'] if v['value']==row[f['key']]),
}
def render(dsl, row, perms):
    if dsl['required_permission'] not in perms:
        return f"{dsl['title']}: 권한 없음"
    return ' | '.join(f"{f['label']}={REG[f['type']](f, row)}" for f in dsl['fields'])

deps = {'svc-ads': {'ui','fetcher'}, 'svc-pay': {'ui','sdk'}, 'svc-admin': {'sdui','ui'},
        'svc-data': {'chart'}, 'sdui': {'ui'}}
def affected(changed):
    out, todo = set(), {changed}
    while todo:
        p = todo.pop()
        for s, ds in deps.items():
            if p in ds and s not in out:
                out.add(s); todo.add(s)
    return sorted(x for x in out if x.startswith('svc-'))
